    def test_reporting_currency_rate_rules(self):
        # Implicit rate when fx_rates omits the reporting currency.
        result = self.service.portfolio_aggregate(
            json.dumps(
                {
                    "reporting_currency": "USD",
                    "fx_rates": {"EUR": 1.1},
                    "positions": [
