                            "id": "p2",
                            "book": "b",
                            "currency": "EUR",
                            "market_value": 10.0,
                            "sensitivities": {"eq": 1.0},
                        },
                    ],
                }
            ).encode("utf-8")
        )
        self.assertEqual(
            self.by(result["currencies"], "currency", "USD")["fx_rate"], 1.0
        )
        # An explicit numeric 1 (int or float) is accepted.
        for explicit in (1, 1.0):
            result = self.call(fx_rates={"EUR": 1.1, "JPY": 0.01, "USD": explicit})
            self.assertEqual(
                self.by(result["currencies"], "currency", "USD")["fx_rate"], 1.0
